CREATE TYPE "Role" AS ENUM ('ADMIN','EDITOR');
CREATE TYPE "AppointmentStatus" AS ENUM ('PENDING','CONFIRMED','COMPLETED','CANCELLED');
CREATE TYPE "ContactStatus" AS ENUM ('NEW','READ','RESOLVED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'EDITOR',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Service" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"titleEn" TEXT NOT NULL,"titleAr" TEXT NOT NULL,"descriptionEn" TEXT NOT NULL,"descriptionAr" TEXT NOT NULL,"imageUrl" TEXT,"published" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Appointment" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"locale" TEXT NOT NULL DEFAULT 'en',"preferredAt" TIMESTAMP(3) NOT NULL,"message" TEXT,"status" "AppointmentStatus" NOT NULL DEFAULT 'PENDING',"serviceId" TEXT NOT NULL REFERENCES "Service"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ContactMessage" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT,"subject" TEXT NOT NULL,"message" TEXT NOT NULL,"locale" TEXT NOT NULL DEFAULT 'en',"status" "ContactStatus" NOT NULL DEFAULT 'NEW',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Media" ("id" TEXT PRIMARY KEY,"path" TEXT NOT NULL UNIQUE,"url" TEXT NOT NULL,"altEn" TEXT,"altAr" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Appointment_status_preferredAt_idx" ON "Appointment"("status","preferredAt");
CREATE INDEX "ContactMessage_status_createdAt_idx" ON "ContactMessage"("status","createdAt");
